// ProviderServiceHandler is an implementation of the toshi.backend.provider.v1.ProviderService
// service.
type ProviderServiceHandler interface {
	// Open starts the provider with its settings and returns what does not
	// change while it runs: its name, its capabilities, the facets it offers
	// and the other constants of the contract. A second Open with the same
	// config, as after a reconnect to the same process, returns the first
	// answer; another config fails with FAILED_PRECONDITION.
	Open(context.Context, *connect.Request[providerv1.OpenRequest]) (*connect.Response[providerv1.OpenResponse], error)
	// Create creates an instance of spec and returns it, usually still
	// creating. The spec's workspace and key, with operation_id, are the
	// operation's identity: a retried Create with the same operation_id
	// returns the first one's outcome, waiting for it when it is still running.
	// A Create with a new operation_id on a key another instance holds fails
	// with ERROR_CODE_KEY_IN_USE; it never makes a second instance. A Create
	// whose call is cancelled answers once the provider has undone what it
	// made; when it cannot confirm that, it fails with ERROR_CODE_NO_REPLY and
	// the operation in the error.
	Create(context.Context, *connect.Request[providerv1.CreateRequest]) (*connect.Response[providerv1.CreateResponse], error)
	// CreateOutcome reads back the outcome of a Create or Restore whose answer
	// the caller did not get. It creates nothing. It waits while the operation
	// runs, up to the call's deadline, and then answers pending; an operation
	// the provider has no record of is unknown.
	CreateOutcome(context.Context, *connect.Request[providerv1.CreateOutcomeRequest]) (*connect.Response[providerv1.CreateOutcomeResponse], error)
	// Get returns the instance as it is now.
	Get(context.Context, *connect.Request[providerv1.GetRequest]) (*connect.Response[providerv1.GetResponse], error)
	// List returns every instance the provider knows that is not destroyed.
	List(context.Context, *connect.Request[providerv1.ListRequest]) (*connect.Response[providerv1.ListResponse], error)
	// Start starts a ready or stopped instance. From another state it fails
	// with ERROR_CODE_INVALID_TRANSITION, on a retry too.
	Start(context.Context, *connect.Request[providerv1.StartRequest]) (*connect.Response[providerv1.StartResponse], error)
	// Stop stops a running instance. From another state it fails with
	// ERROR_CODE_INVALID_TRANSITION, on a retry too.
	Stop(context.Context, *connect.Request[providerv1.StopRequest]) (*connect.Response[providerv1.StopResponse], error)
	// Destroy destroys the instance and everything it holds on the host. It
	// succeeds for an instance that is already destroyed or unknown.
	Destroy(context.Context, *connect.Request[providerv1.DestroyRequest]) (*connect.Response[providerv1.DestroyResponse], error)
	// Wait returns the instance once it is in state want, or fails when it
	// reaches a state it cannot leave for want or when the call's deadline
	// passes. A failure carries the instance as it last was in the error.
	Wait(context.Context, *connect.Request[providerv1.WaitRequest]) (*connect.Response[providerv1.WaitResponse], error)
	// CreateCacheBase creates an empty cache disk of size_gib at path.
	CreateCacheBase(context.Context, *connect.Request[providerv1.CreateCacheBaseRequest]) (*connect.Response[providerv1.CreateCacheBaseResponse], error)
	// CreateCacheOverlay creates a cache disk at path on top of backing.
	CreateCacheOverlay(context.Context, *connect.Request[providerv1.CreateCacheOverlayRequest]) (*connect.Response[providerv1.CreateCacheOverlayResponse], error)
	// CacheRequiredBytes returns the bytes the cache disk at path needs to be
	// flattened.
	CacheRequiredBytes(context.Context, *connect.Request[providerv1.CacheRequiredBytesRequest]) (*connect.Response[providerv1.CacheRequiredBytesResponse], error)
	// FlattenCache writes the cache disk at path, with its backing, as one
	// disk at dst.
	FlattenCache(context.Context, *connect.Request[providerv1.FlattenCacheRequest]) (*connect.Response[providerv1.FlattenCacheResponse], error)
	// AttachDisk attaches a disk to a running instance.
	AttachDisk(context.Context, *connect.Request[providerv1.AttachDiskRequest]) (*connect.Response[providerv1.AttachDiskResponse], error)
	// DiskHasData reports whether the disk at path holds data.
	DiskHasData(context.Context, *connect.Request[providerv1.DiskHasDataRequest]) (*connect.Response[providerv1.DiskHasDataResponse], error)
	// ExportDisk writes the disk at src to dst, a file it creates, as one
	// disk that needs no other file.
	ExportDisk(context.Context, *connect.Request[providerv1.ExportDiskRequest]) (*connect.Response[providerv1.ExportDiskResponse], error)
	// InstanceGone reports whether an instance a previous agent left on the
	// host is positively gone.
	InstanceGone(context.Context, *connect.Request[providerv1.InstanceGoneRequest]) (*connect.Response[providerv1.InstanceGoneResponse], error)
	// Unreaped reports how many instance directories the provider's start-up
	// scan could not confirm gone.
	Unreaped(context.Context, *connect.Request[providerv1.UnreapedRequest]) (*connect.Response[providerv1.UnreapedResponse], error)
	// Snapshot saves a running instance and returns the snapshot's id.
	Snapshot(context.Context, *connect.Request[providerv1.SnapshotRequest]) (*connect.Response[providerv1.SnapshotResponse], error)
	// Restore creates an instance of spec from a snapshot, with Create's rules
	// for operation_id, a held key and a cancelled call.
	Restore(context.Context, *connect.Request[providerv1.RestoreRequest]) (*connect.Response[providerv1.RestoreResponse], error)
	// ImageIdentity returns the identity of the image spec names.
	ImageIdentity(context.Context, *connect.Request[providerv1.ImageIdentityRequest]) (*connect.Response[providerv1.ImageIdentityResponse], error)
	// SnapshotImageIdentity returns the identity of the image a snapshot was
	// made from.
	SnapshotImageIdentity(context.Context, *connect.Request[providerv1.SnapshotImageIdentityRequest]) (*connect.Response[providerv1.SnapshotImageIdentityResponse], error)
	// SetSnapshotRefs tells the provider which snapshots the agent's warm
	// pools hold, for its collector.
	SetSnapshotRefs(context.Context, *connect.Request[providerv1.SetSnapshotRefsRequest]) (*connect.Response[providerv1.SetSnapshotRefsResponse], error)
	// Collect removes what nothing has used for grace, at most max_per_pass
	// items, and returns the bytes it freed.
	Collect(context.Context, *connect.Request[providerv1.CollectRequest]) (*connect.Response[providerv1.CollectResponse], error)
	// Forget drops a destroyed instance from the provider's records.
	Forget(context.Context, *connect.Request[providerv1.ForgetRequest]) (*connect.Response[providerv1.ForgetResponse], error)
	// BaseImages lists the bases an image version can be an overlay on.
	BaseImages(context.Context, *connect.Request[providerv1.BaseImagesRequest]) (*connect.Response[providerv1.BaseImagesResponse], error)
	// CaptureDisk writes the root disk of a stopped instance to dst, a file
	// it creates, as a compressed qcow2 overlay whose backing file is named by
	// the base image's file name alone. dst is replaced only once it is
	// complete. A running instance fails with ERROR_CODE_INVALID_TRANSITION;
	// an instance with a state volume or booted from an image version, or a
	// base whose SHA-256 the provider does not know, with
	// ERROR_CODE_UNSUPPORTED; a base that changed on disk since the instance
	// booted, with ERROR_CODE_IMAGE_CHANGED. An empty id fails with
	// ERROR_CODE_NOT_FOUND, so a client can tell a program that serves the
	// call from one that does not.
	CaptureDisk(context.Context, *connect.Request[providerv1.CaptureDiskRequest]) (*connect.Response[providerv1.CaptureDiskResponse], error)
	// Describe returns the backend facets the provider offers and its
	// capabilities.
	Describe(context.Context, *connect.Request[providerv1.DescribeRequest]) (*connect.Response[providerv1.DescribeResponse], error)
	// Preflight checks the host before the provider starts: the facet
	// "preflighter".
	Preflight(context.Context, *connect.Request[providerv1.PreflightRequest]) (*connect.Response[providerv1.PreflightResponse], error)
	// Status reports what the provider keeps on the host: the facet
	// "status_reporter".
	Status(context.Context, *connect.Request[providerv1.StatusRequest]) (*connect.Response[providerv1.StatusResponse], error)
	// IdleMemoryMiB returns the memory an idle instance of spec keeps, or 0
	// when the provider reclaims none for it.
	IdleMemoryMiB(context.Context, *connect.Request[providerv1.IdleMemoryMiBRequest]) (*connect.Response[providerv1.IdleMemoryMiBResponse], error)
	// SetMemoryTarget asks a running instance's guest to shrink or grow to
	// target_mib.
	SetMemoryTarget(context.Context, *connect.Request[providerv1.SetMemoryTargetRequest]) (*connect.Response[providerv1.SetMemoryTargetResponse], error)
	// MemoryMiB returns the memory a running instance's guest holds now.
	MemoryMiB(context.Context, *connect.Request[providerv1.MemoryMiBRequest]) (*connect.Response[providerv1.MemoryMiBResponse], error)
	// GuestAvailableMiB returns the free memory inside a running instance's
	// guest.
	GuestAvailableMiB(context.Context, *connect.Request[providerv1.GuestAvailableMiBRequest]) (*connect.Response[providerv1.GuestAvailableMiBResponse], error)
	// SetMemoryHigh sets the memory level above which the instance's processes
	// are throttled.
	SetMemoryHigh(context.Context, *connect.Request[providerv1.SetMemoryHighRequest]) (*connect.Response[providerv1.SetMemoryHighResponse], error)
	// Usage returns what an instance has used so far.
	Usage(context.Context, *connect.Request[providerv1.UsageRequest]) (*connect.Response[providerv1.UsageResponse], error)
	// HostMemory returns the host memory an instance holds now, in bytes.
	HostMemory(context.Context, *connect.Request[providerv1.HostMemoryRequest]) (*connect.Response[providerv1.HostMemoryResponse], error)
	// ProcessLimit returns an instance's process limit and how close it came.
	ProcessLimit(context.Context, *connect.Request[providerv1.ProcessLimitRequest]) (*connect.Response[providerv1.ProcessLimitResponse], error)
	// DialGuest connects to a running instance's guest channel. The first
	// request names the instance and carries no data; the first response
	// carries no data and says the connection is made, or the call fails as
	// the dial would. Later frames on both sides carry the channel's bytes
	// unchanged, at most 32 KiB each. The caller closing its side closes the
	// write side to the guest; the guest closing its side ends the call.
	DialGuest(context.Context, *connect.BidiStream[providerv1.DialGuestRequest, providerv1.DialGuestResponse]) error
	// DialDisplay connects to a running instance's display, framed as
	// DialGuest.
	DialDisplay(context.Context, *connect.BidiStream[providerv1.DialDisplayRequest, providerv1.DialDisplayResponse]) error
	// CaptureScreen writes a running instance's screen to path as one PNG of
	// at most OpenResponse.max_screen_bytes bytes. On success the file is
	// complete. After ERROR_CODE_NO_REPLY the file may still be written until
	// the instance is destroyed; after any other error nothing is at path.
	CaptureScreen(context.Context, *connect.Request[providerv1.CaptureScreenRequest]) (*connect.Response[providerv1.CaptureScreenResponse], error)
	// ReadConsole reads an instance's serial console from (start, offset) on.
	// When nothing is past offset yet it waits up to wait for more, then
	// answers with no data.
	ReadConsole(context.Context, *connect.Request[providerv1.ReadConsoleRequest]) (*connect.Response[providerv1.ReadConsoleResponse], error)
	// KeepConsoleLog keeps an instance's console log past its destroy and
	// returns the log's path.
	KeepConsoleLog(context.Context, *connect.Request[providerv1.KeepConsoleLogRequest]) (*connect.Response[providerv1.KeepConsoleLogResponse], error)
	// DebugSSHAddr returns the host loopback address that reaches the
	// instance's debug ssh port.
	DebugSSHAddr(context.Context, *connect.Request[providerv1.DebugSSHAddrRequest]) (*connect.Response[providerv1.DebugSSHAddrResponse], error)
	// PreviewAddr returns the host loopback address that reaches the
	// instance's preview port, and that port.
	PreviewAddr(context.Context, *connect.Request[providerv1.PreviewAddrRequest]) (*connect.Response[providerv1.PreviewAddrResponse], error)
	// BindingAddr returns the host loopback address that reaches the
	// instance's binding port, the port a Linux guest's helper accepts the
	// host's connections for bound services on.
	BindingAddr(context.Context, *connect.Request[providerv1.BindingAddrRequest]) (*connect.Response[providerv1.BindingAddrResponse], error)
}

